/**
 * The curated Piper voice catalog (rhasspy/piper-voices, MIT): which voices
 * the app offers, what they are called, and how a GENERATE `voice` string
 * names one. The catalog itself is generated by scripts/pin-piper-voices.mjs
 * into src/workers/manifests/piperVoices.ts; this module adds the types and
 * lookups, and keeps the rules for what may be listed in one place.
 *
 * Only voices whose dataset license permits commercial use with attribution
 * (public domain, CC0, CC BY, Apache-2.0, MIT) are listed, and only voices
 * the English eSpeak phonemizer can drive are playable: the app ships an
 * English-only phonemizer, so other locales are left out of the catalog
 * rather than listed as unavailable.
 */
import { PIPER_CATALOG } from "../workers/manifests/piperVoices";
import type { PinnedAssetManifest } from "./pinnedModelFetch";

export const PIPER_PERMISSIVE_LICENSES = ["public-domain", "CC0-1.0", "CC-BY-4.0", "Apache-2.0", "MIT"] as const;
export type PiperLicenseId = (typeof PIPER_PERMISSIVE_LICENSES)[number];

export type PiperQuality = "x_low" | "low" | "medium" | "high";

export interface PiperVoiceEntry {
  /** `<locale>-<speaker>-<quality>`, such as "en_US-kristin-medium"; the GENERATE `voice` value. */
  readonly id: string;
  /** Display name of the speaker or dataset, such as "Kristin". */
  readonly name: string;
  /** `en_US` or `en_GB`. */
  readonly locale: string;
  readonly language: string;
  readonly quality: PiperQuality;
  readonly sampleRate: number;
  /** 1 for single-speaker voices; GENERATE picks one with `<id>#<speaker>`. */
  readonly numSpeakers: number;
  /** The eSpeak voice the model was trained with (from its .onnx.json). */
  readonly espeakVoice: string;
  /** Repository paths of the graph and its config; both are listed in the catalog's `files`. */
  readonly model: string;
  readonly config: string;
  readonly license: {
    readonly id: PiperLicenseId;
    readonly url: string | null;
  };
  /** Where the training data comes from (the voice's MODEL_CARD). */
  readonly datasetUrl: string | null;
  /** Credit line to show next to the voice. */
  readonly attribution: string;
}

/** The pinned repository files (graphs and configs) plus the voices they make up. */
export interface PiperCatalog extends PinnedAssetManifest {
  readonly voices: readonly PiperVoiceEntry[];
}

export const PIPER_VOICES: readonly PiperVoiceEntry[] = PIPER_CATALOG.voices;
export const PIPER_DEFAULT_VOICE = "en_US-kristin-medium";
export const PIPER_CACHE_NAME = "transformers-cache-piper-v1";

/** Only English eSpeak voices work with the phonemizer the app ships. */
export function isEnglishEspeakVoice(espeakVoice: string): boolean {
  return /^en(?:-|$)/.test(espeakVoice);
}

export function findPiperVoice(id: string): PiperVoiceEntry | undefined {
  return PIPER_VOICES.find((voice) => voice.id === id);
}

export interface PiperVoiceRef {
  voice: PiperVoiceEntry;
  /** A speaker name from the voice's speaker_id_map or a numeric id; null for the first speaker. */
  speaker: string | null;
}

/**
 * Resolves a GENERATE `voice` such as "en_GB-vctk-medium#p239" or
 * "en_GB-vctk-medium#7". An unknown voice falls back to the default, because
 * the app keeps one voice selection across models.
 */
export function resolvePiperVoice(value: string): PiperVoiceRef {
  const separator = value.indexOf("#");
  const id = separator < 0 ? value : value.slice(0, separator);
  const speaker = separator < 0 ? "" : value.slice(separator + 1);
  const voice = findPiperVoice(id) ?? findPiperVoice(PIPER_DEFAULT_VOICE);
  if (!voice) throw new Error("The Piper voice catalog has no default voice.");
  return { voice, speaker: voice.numSpeakers > 1 && speaker ? speaker : null };
}
